window.ScripturaLexicons.BDAG_PART_0226 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0226-01\" data-source=\"BDAG\" data-search=\"Μάρθα, ας, ἡ nome próprio feminino Marta, irmã de Maria e Lázaro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Μάρθα, ας, ἡ</td><td>nome próprio feminino</td><td>Marta, irmã de Maria e Lázaro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0226-02\" data-source=\"BDAG\" data-search=\"Μαρία, ας, ἡ nome próprio feminino Maria, nome de diversas mulheres BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Μαρία, ας, ἡ</td><td>nome próprio feminino</td><td>Maria, nome de diversas mulheres</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0226-03\" data-source=\"BDAG\" data-search=\"Μαριάμ, ἡ nome próprio feminino Miriã, irmã de Moisés e Arão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Μαριάμ, ἡ</td><td>nome próprio feminino</td><td>Miriã, irmã de Moisés e Arão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0226-04\" data-source=\"BDAG\" data-search=\"Μαρκίων, ωνος, ὁ nome próprio masculino Marcião, dois personagens BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Μαρκίων, ωνος, ὁ</td><td>nome próprio masculino</td><td>Marcião, dois personagens</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0226-05\" data-source=\"BDAG\" data-search=\"Μαρκιωνιστής, οῦ, ὁ substantivo masculino marcionita, seguidor de Marcião BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Μαρκιωνιστής, οῦ, ὁ</td><td>substantivo masculino</td><td>marcionita, seguidor de Marcião</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0226-06\" data-source=\"BDAG\" data-search=\"Μᾶρκος, ου, ὁ nome próprio masculino Marcos, João Marcos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Μᾶρκος, ου, ὁ</td><td>nome próprio masculino</td><td>Marcos, João Marcos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0226-07\" data-source=\"BDAG\" data-search=\"μάρμαρος, ου, ὁ substantivo masculino mármore BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μάρμαρος, ου, ὁ</td><td>substantivo masculino</td><td>mármore</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0226-08\" data-source=\"BDAG\" data-search=\"Μάρτιος, ίου, ὁ nome próprio masculino março, mês do ano BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Μάρτιος, ίου, ὁ</td><td>nome próprio masculino</td><td>março, mês do ano</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0226-09\" data-source=\"BDAG\" data-search=\"μαρτυρέω verbo testemunhar; confirmar; aprovar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μαρτυρέω</td><td>verbo</td><td>testemunhar; confirmar; aprovar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0226-10\" data-source=\"BDAG\" data-search=\"μαρτυρία, ας, ἡ substantivo feminino testemunho; depoimento; martírio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μαρτυρία, ας, ἡ</td><td>substantivo feminino</td><td>testemunho; depoimento; martírio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0226-11\" data-source=\"BDAG\" data-search=\"μαρτύριον, ου, τό substantivo neutro testemunho; prova; martírio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μαρτύριον, ου, τό</td><td>substantivo neutro</td><td>testemunho; prova; martírio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0226-12\" data-source=\"BDAG\" data-search=\"μαρτύρομαι verbo médio testemunhar; insistir; implorar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μαρτύρομαι</td><td>verbo médio</td><td>testemunhar; insistir; implorar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0226-13\" data-source=\"BDAG\" data-search=\"μάρτυς, μάρτυρος, ὁ substantivo masculino testemunha; mártir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μάρτυς, μάρτυρος, ὁ</td><td>substantivo masculino</td><td>testemunha; mártir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0226-14\" data-source=\"BDAG\" data-search=\"μαρυκάομαι verbo médio ruminar; remoer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μαρυκάομαι</td><td>verbo médio</td><td>ruminar; remoer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0226-15\" data-source=\"BDAG\" data-search=\"μασάομαι verbo médio morder BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μασάομαι</td><td>verbo médio</td><td>morder</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0226-16\" data-source=\"BDAG\" data-search=\"μασθός remissão ver μαστός BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μασθός</td><td>remissão</td><td>ver μαστός</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0226-17\" data-source=\"BDAG\" data-search=\"μαστιγόω verbo açoitar; flagelar; corrigir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μαστιγόω</td><td>verbo</td><td>açoitar; flagelar; corrigir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0226-18\" data-source=\"BDAG\" data-search=\"μαστίζω verbo golpear com chicote; flagelar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μαστίζω</td><td>verbo</td><td>golpear com chicote; flagelar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0226-19\" data-source=\"BDAG\" data-search=\"μάστιξ, ιγος, ἡ substantivo feminino açoite; sofrimento; doença BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μάστιξ, ιγος, ἡ</td><td>substantivo feminino</td><td>açoite; sofrimento; doença</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0226-20\" data-source=\"BDAG\" data-search=\"μαστός, οῦ, ὁ substantivo masculino mamilo; seio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μαστός, οῦ, ὁ</td><td>substantivo masculino</td><td>mamilo; seio</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0226-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μάρθα, ας, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Μάρθα</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"hebrew\" dir=\"rtl\">מָרְתָּא</span>, “senhora”; ver B-D-F §53, 3. Plut., Mar. 414 [17, 2] <span class=\"greek\">Σύραν</span> <span class=\"greek\">γυναῖκα</span>, <span class=\"greek\">Μάρθαν</span> <span class=\"greek\">ὄνομα</span>; BGU 1153 I, 3 [14 a.C.]; 1155, 4 [10 a.C.]), Marta, segundo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:38</a>, 40s., irmã de Maria (JBrutscheck, Die Maria-Marta-Erzählung ’86; WCarter, CBQ 58, ’96, 264–80); segundo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.1\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:1</a>, 5, 19ss., 24, 30, 39, também irmã de Lázaro de Betânia.—12:2.—BHHW II 1156. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0226-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μαρία, ας, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Μαρία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (inscrição num vaso proveniente de Samaria-Sebaste: SEG VIII, 110 [século I a.C./I d.C.]; dois óstracos: PMeyer, n.os 33 e 56 [ambos do século II d.C.]; ver Dssm., LO 97s.; 302; terceiro óstraco em Dssm., LO 260 [ver LAE2 121, n. 11; 122; 306, n. 6: a adição do nome da mãe é regular nos textos mágicos]; Jos., Bell. 6, 201; Just., Mel.) e <span class=\"greek\">Μαριάμ</span> indeclinável (<span class=\"hebrew\" dir=\"rtl\">מִרְיָם</span>, Miriã [profetisa e irmã de Moisés, Ex 15:20s.; Demetr.: 722 Fgm. 2, 3 Jac.; Ezech. Trag. 5, 18 e 23 em Clem. of Al., Strom. 1, 23, 155, 4; Philo; Just., D. 78, 3] 1 Cl 4:11) e <span class=\"greek\">Μαριάμμη</span> (GMary 463, 3; GJs 16:3; 17:2s.—Joseph. escreve o nome <span class=\"greek\">Μαριά</span>[<span class=\"greek\">μ</span>]<span class=\"greek\">μη</span>, <span class=\"greek\">ης</span> [Ant. 3, 54].—Sobre o nome e suas diferentes formas, ver B-D-F §53, 3; Mlt-H. 144s.; OBardenhewer, Der Name Maria 1895; HvSoden, Die Schriften des NTs I 1906, 1373s.; FZorell, ZKT 30, 1906, 356ss.; EKönig, ZNW 17, 1916, 257–63; MNoth, D. isr. Personennamen 1929; WvonSoden, Bibel u. Alter Orient: ZAW Beih. 162, 129–33; MGörg, BZ ’79, 285–89), Maria.</p><p class=\"entry-text\">① Mãe de Jesus. As seguintes formas do nome estão documentadas nos diversos casos: <span class=\"greek\">Μαρία</span> como nominativo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:19</a>; de resto, somente ocasionalmente como variante textual (D <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:30</a>, 39, 56; cf. vv. 34, 38, 46). Genitivo <span class=\"greek\">Μαρίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:16</a>, 18; 2:11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:41</a>; IEph 7:2; 18:2; 19:1; ITr 9:1; AcPlCor 1:14; 2:5. Acusativo <span class=\"greek\">Μαρίαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:20</a> (variante -<span class=\"greek\">άμ</span>); AcPl Ha 8, 26; <span class=\"greek\">Μ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">Γαλιλαίαν</span> AcPlCor 2:14.—<span class=\"greek\">Μαριάμ</span> como nominativo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:16</a> variante; 13:55; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:27</a>, 34, 38s., 46, 56; 2:19 (variante -<span class=\"greek\">ρία</span>); como acusativo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:20</a> variante; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:16</a>; GJs 6:3 (não Bodmer); como vocativo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:30</a>; <span class=\"greek\">σὺν</span> <span class=\"greek\">Μαριάμ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:14</a>; <span class=\"greek\">πρὸς</span> <span class=\"greek\">Μαριάμ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:34</a>. Pouco se sabe da vida desta Maria; nos relatos da infância Mt 1s.; Lk 1s. e especialmente nos evangelhos apócrifos (29 ocorrências em GJs; ver AFuchs, Konkordanz), ela desempenha papel importante; ver WBauer, D. Leben Jesu im Zeitalter d. ntl. Apokryphen 1909; HUsener, ZNW 4, 1903, 1ss. Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:31</a>s. e paralelos, onde ela e os irmãos e irmãs de Jesus são mencionados destacadamente, não se indica qualquer interesse no movimento dele. Mas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:14</a> menciona Maria e os irmãos dele (irmãos e irmãs? ver <span class=\"greek\">ἀδελφός</span> 1) entre os membros da igreja primitiva. A mãe de Jesus também é mencionada no Quarto Evangelho, embora não nominalmente.—RSeeberg, Die Herkunft der Mutter Jesu: Bonwetsch Festschr. 1918, 13ss.; JBlinzler, Jes. u. s. Mutter nach dem Zeugn. der Evv.: Klerusblatt 23, ’42; 24, ’43; UHolzmeister, De anno mortis Deip. Virg.: Marianum 4, ’42, 167–82; FWillam, D. Leb. Marias3 ’42; HRäisänen, D. Mutter Jesu im NT, ’69; JMcHugh, The Mother of Jesus in the NT ’75; RBrown, KDornfried e outros, Mary in the NT ’78; RBrown, The Birth of the Messiah ’77.—ABD IV 586 (bibliografia). LexThK VII 25–28. TRE XXII 115–19. EDNT. II 386s.</p><p class=\"entry-text\">② Maria Madalena (ver <span class=\"greek\">Μαγδαληνή</span>). Formas de seu nome: <span class=\"greek\">Μαρία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.56\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:56</a>; 61 variante; 28:1 variante; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:40</a>, 47; 16:1, 9 (<span class=\"greek\">Μαρίᾳ</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:2</a>; 24:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.25\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:25</a>; 20:1, 11, 16 variante, 18 variante. <span class=\"greek\">Μαριάμ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.56\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:56</a> variante, 61; 28:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:40</a> variante; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.25\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:25</a> variante; 20:1 variante, 11 variante, 16 (vocativo), 18; GPt 12:50. Segundo os evangelhos, essa mulher, uma das seguidoras mais fiéis de Jesus, foi curada por ele de possessão por sete espíritos hostis (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:2</a>). Ela aparece na narrativa da Paixão com outras mulheres, também no relato sinótico da manhã de Páscoa. Em João, é a única mencionada junto ao sepulcro e vê o Senhor ressuscitado (igualmente no final longo de Marcos). Rumores eclesiásticos posteriores identificaram-na, sem fundamento, com a pecadora que ungiu Jesus na casa do fariseu (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:37</a>, 39). CLattey: Exp 7th ser., 8, 1909, 55–63; UHolzmeister, Die Magdalenenfrage in der kirchl. Überl.: ZKT 46, 1922, 402ss.; JSickenberger, Ist die Magdalenenfrage wirklich unlösbar? BZ 17, 1926, 63ss.; PKetter, D. Magdalenenfrage 1929; RBruckberger, M. Magdalena, ’54; MHengel, M. Magdalena u. d. Frauen als Zeugen: FMichel, ’63, 243–56; AMarjanen, The Woman Jesus Loved ’96 (Nag Hammadi); HMelzer-Keller, Geist und Leben 72, ’99, 97–111. LexThK VII 39s.; BHHW II 1151. Ver Simpson e Burkitt sob ⑤ adiante.</p><p class=\"entry-text\">③ A “outra” Maria, mãe de Tiago (ver <span class=\"greek\">Ἰάκωβος</span> 3) e de José (ver <span class=\"greek\">Ἰωσῆς</span> 2). Forma do nome <span class=\"greek\">Μαρία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.56\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:56</a>, 61 (<span class=\"greek\">ἡ</span> <span class=\"greek\">ἄλλη</span> <span class=\"greek\">Μαρία</span>; cf. PPetr III, 59[c]); 28:1 (<span class=\"greek\">ἡ</span> <span class=\"greek\">ἄλλ</span>. <span class=\"greek\">Μ</span>.—JMackay, The Other M.: ET 40, 1929, 319–21); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:40</a>, 47; 16:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:10</a>. Foi uma das seguidoras de Jesus presentes como espectadoras dos acontecimentos no Gólgota. Por isso, pode ser idêntica a:</p><p class=\"entry-text\">④ <span class=\"greek\">Μαρία</span> (variante <span class=\"greek\">Μαριάμ</span>) <span class=\"greek\">ἡ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Κλωπᾶ</span> <span class=\"greek\">Μ</span>., esposa de Clopas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.25\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:25</a>.</p><p class=\"entry-text\">⑤ Maria, segundo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:39</a>, 42, irmã de Marta; segundo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.1\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:1</a>s., 19s., 28, 31s., 45; 12:3, também irmã de Lázaro, residente em Betânia. Formas do nome: <span class=\"greek\">Μαρία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:39</a> variante, 42 variante; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:2</a> variante, 20 variante, 32 variante; 12:3 variante; <span class=\"greek\">Μαρίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.1\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:1</a>; <span class=\"greek\">Μαρίαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:19</a> variante, 28 variante, 31 variante, 45 variante. <span class=\"greek\">Μαριάμ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:39</a>, 42; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:2</a>, 20, 32; 12:3; como acusativo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:19</a>, 28, 31, 45.—ASimpson, M. of Bethany, M. of Magdala, and Anonyma: ET 20, 1909, 307–18; FBurkitt, M. Magd. and M., Sister of Martha: ET 42, ’31, 157–59.</p><p class=\"entry-text\">⑥ Mãe de João Marcos, proprietária de uma casa em Jerusalém (<span class=\"greek\">οἰκία</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Μαρίας</span>), a qual colocou à disposição dos cristãos para reuniões <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:12</a>.</p><p class=\"entry-text\">⑦ Outra cristã, de resto desconhecida, provavelmente de ascendência judaica (embora <span class=\"greek\">Μαρία</span> apareça em CB I/2, 557s. n.os 439 e 440 como forma feminina do nome romano Marius), saudada em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:6</a> (<span class=\"greek\">ἀσπάσασθε</span> <span class=\"greek\">Μαρίαν</span>; variante <span class=\"greek\">Μαριάμ</span> [já em P46]), com a informação adicional de que ela prestara serviço extraordinário aos destinatários da carta.—EDNT. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0226-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μαριάμ, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Μαριάμ</span>, <span class=\"greek\">ἡ</span>, indeclinável (sobre a forma do nome, ver o começo do verbete anterior), Miriã, profetisa e irmã de Arão e Moisés (Ex 15:20s.; Num 12) 1 Cl 4:11.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0226-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μαρκίων, ωνος, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Μαρκίων</span>, <span class=\"greek\">ωνος</span>, <span class=\"greek\">ὁ</span>, Marcião, nome raro (Sb 4604, 3).</p><p class=\"entry-text\">① Um cristão de Esmirna MPol 20:1 (também se atesta <span class=\"greek\">Μάρκου</span>, assim como a forma <span class=\"greek\">Μαρκιανοῦ</span>, presente na versão latina e preferida por Lghtf.; a esse respeito, ver OvGebhardt, ZWT18, 1875, 370ss.).</p><p class=\"entry-text\">② O conhecido heresiarca EpilMosq 3 (Just., A I, 26, 5; 58, 1).—AvHarnack, Marcion2 1924; MEnslin, The Pontic Mouse: ATR 27, ’45, 1–16.—ABD IV 514–20.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0226-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μαρκιωνιστής, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Μαρκιωνιστής</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span>, marcionita, seguidor de Marcião EpilMosq 3 (ver <span class=\"greek\">Μαρκίων</span> 2).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0226-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μᾶρκος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Μᾶρκος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (sobre a acentuação, ver B-D-F §41, 3; Rob. 235), Marcos, nome relativamente frequente (Diod S 11, 63, 1; Plut., inscrições, papiros; Philo, Leg. ad Gai. 62; 294; Joseph.; Just., D. 141, 5; Ath. [ins]), sobrenome de João (ver <span class=\"greek\">Ἰωάν</span>[<span class=\"greek\">ν</span>]<span class=\"greek\">ης</span> 6), filho de Maria de Jerusalém (ver <span class=\"greek\">Μαρία</span> 6). Talvez apresentado a Paulo por Barnabé, seu primo (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:10</a>); acompanhou Paulo e Barnabé na chamada primeira viagem missionária, mas os deixou antes de sua conclusão e mais tarde se tornou motivo de ruptura aberta entre os dois. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:12</a>, 25; 15:37, 39. Certamente a mesma pessoa é referida em Phlm 24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:13</a>. Título do segundo evangelho: <span class=\"greek\">κατὰ</span> <span class=\"greek\">Μᾶρκον</span>; cf. Papias (2:14) (quanto aos dois nomes de um homem ativo e conhecido entre semitas e gregos, pode-se comparar o cartaginês <span class=\"greek\">Ἀσδρούβας</span> [Asdrúbal, século II a.C.], conhecido entre os gregos como <span class=\"greek\">Κλειτόμαχος</span> [Diog. L. 4, 67]). <span class=\"greek\">Μ</span>. … <span class=\"greek\">ἑρμηνευτὴς</span> <span class=\"greek\">Πέτρου</span> <span class=\"greek\">γενόμενος</span> Papias (2:15).—Zahn, Einl. II3 204ss.; Jülicher, RE XII 288ss.; EBarnikol, Personenprobleme d. AG, Joh. Markus, Silas u. Titus ’31; WReilly, CBQ 1, ’39, 223–31; RTaylor, ET 54, ’43, 136–38; KNiederwimmer, ZNW 58, ’67, 172–87.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0226-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μάρμαρος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μάρμαρος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Hom. e outros, no sentido de “pedra, bloco de rocha”), mármore (assim desde Theophr., Lap. 9; Strabo 9, 1, 23; IG IV2/1, 109 III, 103 [século III a.C.]; PLeid X, 10, 12; BGU 952, 10; EpJer 71; Jos., Bell. 4, 532; masculino e feminino; neutro em TestSol), como material precioso <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:12</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0226-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μάρτιος, ίου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Μάρτιος</span>, <span class=\"greek\">ίου</span>, <span class=\"greek\">ὁ</span> (empréstimo latino: Martius), março. <span class=\"greek\">πρὸ</span> <span class=\"greek\">ἑπτὰ</span> <span class=\"greek\">καλανδῶν</span> <span class=\"greek\">Μαρτίων</span>=23 de fevereiro, MPol 21.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0226-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαρτυρέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μαρτυρέω</span>, imperfeito <span class=\"greek\">ἐμαρτύρουν</span>; futuro <span class=\"greek\">μαρτυρήσω</span>; 1º aoristo <span class=\"greek\">ἐμαρτύρησα</span>; perfeito <span class=\"greek\">μεμαρτύρηκα</span>. Passivo: imperfeito <span class=\"greek\">ἐμαρτυρούμην</span>; 1º aoristo <span class=\"greek\">ἐμαρτυρήθην</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:2</a>, 4, 39; perfeito <span class=\"greek\">μεμαρτύρημαι</span> (ver os quatro verbetes seguintes; Semonides, Hdt. e posteriores).</p><p class=\"entry-text\">① Confirmar ou atestar alguma coisa com base no conhecimento ou na convicção pessoal: dar testemunho, ser testemunha.</p><p class=\"entry-text\">ⓐ Prestar depoimento.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Voz ativa: <span class=\"greek\">ὑμεῖς</span> <span class=\"greek\">μαρτυρεῖτε</span>, vós sois testemunhas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.27\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:27</a>. <span class=\"greek\">ἐὰν</span> <span class=\"greek\">θέλωσιν</span> <span class=\"greek\">μαρτυρεῖν</span>, caso estejam dispostos a comparecer como testemunhas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:5</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.17\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:17</a>; 1J 5:6s. Parenteticamente, para enfatizar a correção de uma declaração, <span class=\"greek\">μαρτυρῶ</span>, posso testemunhar (POxy 105, 13 <span class=\"greek\">Σαραπίων</span> <span class=\"greek\">μαρτυρῶ</span>=“Eu, S., sou testemunha”; PLond III, 1164 [f], 35 e outros p. 162.—B-D-F §465, 2; Rob. 434) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:3</a>. <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span>, testemunhar acerca de alguém ou de alguma coisa (PGrenf II, 73, 16 <span class=\"greek\">ὅταν</span> <span class=\"greek\">ἔλθῃ</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">θεῷ</span>, <span class=\"greek\">μαρτυρήσει</span> <span class=\"greek\">σοι</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">ὧν</span> <span class=\"greek\">αὐτὴν</span> <span class=\"greek\">πεποιήκασιν</span>; Jos., C. Ap. 1, 217, Vi. 259) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:7</a>s., 15 (caso bastante provável de <span class=\"greek\">μαρτυρεῖ</span> referir-se ao passado, cf. Caecil. Calact., Fgm. 75 p. 58, 2ss., onde se apresentam exemplos da alternância dos tempos: Demosth. 59, 34 <span class=\"greek\">τοὺς</span> <span class=\"greek\">ὁρῶντας</span> em lugar de <span class=\"greek\">τ</span>. <span class=\"greek\">ἑωρακότας</span>; Eur., Androm. Fgm. 145 Nauck2 <span class=\"greek\">ὁρῶ</span> <span class=\"greek\">ἀντὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">εἶδον</span>; Thu. 2, 35, 1 <span class=\"greek\">ἐπαινοῦσι</span> <span class=\"greek\">ἀντὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἐπῄνεσαν</span>); 2:25; 5:31, 32a, 36s., 39; 7:7; 8:13s., 18ab; 10:25; 15:26; 21:24; 1J 5:9. <span class=\"greek\">μαρτύρησον</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κακοῦ</span>, testemunha acerca do mal <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:23</a> (<span class=\"greek\">μ</span>.=apresentar prova, X., Symp. 8, 12). Também <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:4b</a> (sobre <span class=\"greek\">ἐπί</span> com dativo nessa passagem, ver Gen 4:4). Com dativo da coisa (Jos., Ant. 12, 135; Ath. 16, 3 <span class=\"greek\">τῷ</span> <span class=\"greek\">λόγω</span>. <span class=\"greek\">Πλάτων</span>) <span class=\"greek\">μ</span>. <span class=\"greek\">τῇ</span> <span class=\"greek\">ἀληθείᾳ</span>, testemunhar a favor da verdade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.33\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:33</a>; 18:37. <span class=\"greek\">μ</span>. <span class=\"greek\">σου</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἀληθείᾳ</span>, testemunhar a verdade de tua (conduta) 3J 3; <span class=\"greek\">σου</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἀγάπῃ</span> v. 6. Com dativo da pessoa sobre quem se presta testemunho (Appian, Bell. Civ. 3, 73 §298; Just., D. 122, 2.—Trata-se de dativo de interesse favorável ou desfavorável) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.43\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:43</a>; 22:5; GJs 15:2; com particípio seguinte (<span class=\"greek\">μ</span>. <span class=\"greek\">Ἰακὼβ</span> <span class=\"greek\">λέγων</span> Did., Gen. 221, 2) <span class=\"greek\">θεὸς</span> <span class=\"greek\">ἐμαρτύρησεν</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">δοὺς</span> <span class=\"greek\">κτλ</span>., Deus lhes deu testemunho ao conceder… <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:8</a> (embora <span class=\"greek\">αὐτοῖς</span> também possa ser relacionado a <span class=\"greek\">δούς</span>); com <span class=\"greek\">ὅτι</span> seguinte, testemunhar acerca de alguém que <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.28\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:13</a>. <span class=\"greek\">μ</span>. <span class=\"greek\">ἑαυτῷ</span>, <span class=\"greek\">ὅτι</span>, testemunhar a respeito de si mesmo que <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:31</a>. O dativo pode também designar a pessoa informada ou instruída pelo testemunho: testemunhar a alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.15\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 22:18</a>.—<span class=\"greek\">μ</span>. <span class=\"greek\">ὅτι</span>, testemunhar que (Aelian, VH 9, 11; Did., Gen. 156, 28) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.34\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:34</a>; 4:44; 12:17, variante textual; 1J 4:14. <span class=\"greek\">ὅτι</span> introduzindo discurso direto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.39\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:39</a>. <span class=\"greek\">μ</span>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ὅτι</span>, testemunhar contra Deus ao declarar que <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:15</a> (PPetr II, 21 [d], 12 [século III a.C.] <span class=\"greek\">καθ</span>’ <span class=\"greek\">οὗ</span> <span class=\"greek\">μαρτυρῶ</span>). <span class=\"greek\">ἐμαρτύρησεν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">εἶπεν</span>, seguido de discurso direto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.21\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:21</a>. <span class=\"greek\">μ</span>. <span class=\"greek\">λέγων</span>, seguido de discurso direto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.32\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:32</a>. Acerca de Deus: <span class=\"greek\">μοι</span> <span class=\"greek\">μαρτυρεῖ</span> <span class=\"greek\">λέγων</span> (segue-se Ps 89:4), ele me dá testemunho disso, dizendo 15:4. Quanto a <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:13</a>, ver ⓒ abaixo.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Voz passiva: receber testemunho, ter testemunho prestado, <span class=\"greek\">ὑπό</span> <span class=\"greek\">τινος</span>, por alguém (Philo, Leg. All. 3, 46 <span class=\"greek\">σοφία</span> <span class=\"greek\">μαρτυρουμένη</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">θεοῦ</span>; Just., D. 63, 5 <span class=\"greek\">Χριστὸς</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ταῦτα</span> <span class=\"greek\">ποιήσαντος</span> <span class=\"greek\">μαρτυρούμενος</span>. De Jesus: <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">προφητῶν</span> <span class=\"greek\">πολλαχοῦ</span> <span class=\"greek\">μεμαρτ</span>. Orig., C. Cels. 2, 9, 30) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:21</a> (o testemunho da lei e dos profetas aponta para a justiça de Deus). Seguido de <span class=\"greek\">ὅτι</span> e de citação em discurso direto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:17</a>. <span class=\"greek\">μαρτυρούμενος</span> <span class=\"greek\">ὅτι</span> <span class=\"greek\">ζῇ</span>, alguém acerca de quem se testemunha que vive v. 8.</p><p class=\"entry-text\">ⓑ Confirmar, dar testemunho de, declarar, ratificar, em voz ativa (Eunap., Vi. Soph. p. 76 <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ἐμαρτύρησε</span>; Iren. 2, 22, 5 [Harv I 331, 1]), <span class=\"greek\">τὶ</span>, alguma coisa (Demosth. 57, 4 <span class=\"greek\">ἀκοήν</span>; Aeschin. 1, 46 <span class=\"greek\">τἀληθῆ</span>). <span class=\"greek\">ὸ</span>̔ <span class=\"greek\">ἑωράκαμεν</span> <span class=\"greek\">μαρτυροῦμεν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:11</a>; cf. v. 32. <span class=\"greek\">τὸν</span> <span class=\"greek\">λόγον</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:2</a>. <span class=\"greek\">ταῦτα</span> 22:20. <span class=\"greek\">τινί</span> <span class=\"greek\">τὶ</span>, alguma coisa a ou em favor de alguém (Dionys. Hal. 3, 67, 1; Jos., Ant. 6, 355) v. 16. <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ζωήν</span> 1J 1:2. O acusativo deve ser suprido pelo contexto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.35\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:11</a>. Com particípio <span class=\"greek\">ἀκούσαντες</span> <span class=\"greek\">μαρτυρήσωσιν</span>, devem admitir que ouviram PtK 3 p. 15, 23.—<span class=\"greek\">μαρτυρίαν</span> <span class=\"greek\">μ</span>., dar testemunho, confirmar, atestar (Ps.-Pla., Eryx. 399b; Epict. 4, 8, 32) <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span>, acerca de alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.32\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:32b</a>; 1J 5:10 (POxy 3313, 25s. <span class=\"greek\">μαρτυρήσει</span> <span class=\"greek\">σοι</span> <span class=\"greek\">Σαραπᾶς</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ῥόδων</span>, S. te confirmará a respeito das rosas).</p><p class=\"entry-text\">ⓒ Sustentar o próprio testemunho com dedicação total, uso eclesiástico relativo ao martírio: testemunhar, ser testemunha (até a morte), sofrer martírio, voz ativa (TestAbr B 11 p. 115, 16 [Stone p. 787] <span class=\"greek\">Ἄβελ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πρώτοις</span> <span class=\"greek\">μαρτυρήσας</span>; Mel., HE 4, 26, 3; <span class=\"greek\">τοῖς</span> <span class=\"greek\">μαρτυρούσι</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">χριστιανισμῷ</span> <span class=\"greek\">μέχρι</span> <span class=\"greek\">θανάτου</span> Orig., C. Cels. 1, 8, 2): a respeito de Paulo <span class=\"greek\">μαρτυρήσας</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἡγουμένων</span> … <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἅγιον</span> <span class=\"greek\">τόπον</span> <span class=\"greek\">ἐπορεύθη</span> 1 Cl 5:7; cf. v. 4; MPol 1:1; 19:1; 21s. (Iren. 3, 3, 4 [Harv. II 12, 8]); EpilMosq 4. Provavelmente também pertence aqui <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:13</a>: <span class=\"greek\">Χριστοῦ</span> <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μαρτυρήσαντος</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">Ποντίου</span> <span class=\"greek\">Πιλάτου</span> <span class=\"greek\">τ</span>. <span class=\"greek\">καλὴν</span> <span class=\"greek\">ὁμολογίαν</span>, Cristo Jesus, que fez a boa confissão diante de Pôncio Pilatos (ver GBaldensperger, RHPR 2, 1922, 1–25; 95–117); de outro modo, a passagem pode ser classificada em ⓐ acima.</p><p class=\"entry-text\">② Afirmar em termos de apoio: dar testemunho favorável, falar bem de, aprovar.</p><p class=\"entry-text\">ⓐ Voz ativa (Dio Chrys. 23 [40], 19; SIG 374, 37 [século III a.C.]; POxy 930, 16), com dativo da pessoa (Appian, Samn. 11, §2 <span class=\"greek\">τοῖς</span> <span class=\"greek\">ὑπάτοις</span>, Liby. 105 §495, Bell. Civ. 4, 92 §387; Aelian, VH 1, 30; Jos., Ant. 12, 134) ou da coisa aprovada <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:22</a> (OFearghus, ZNW 75, ’84, 60–72 [papiros e inscrições]; JNolland, JBL 98, ’79, 219–29); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.26\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:26</a>. Acerca de Deus em relação a Davi <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:22</a>. <span class=\"greek\">μὴ</span> <span class=\"greek\">ἑαυτῷ</span> <span class=\"greek\">μαρτυρείτω</span>, que não testemunhe favoravelmente a respeito de si mesmo 1 Cl 38:2. Com dativo a suprir 3J 12b. <span class=\"greek\">μαρτυρίᾳ</span>, <span class=\"greek\">ᾗ</span> <span class=\"greek\">ἐμαρτύρησεν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">δεσπότης</span> Hs 5, 2, 6. Acerca da carne: <span class=\"greek\">ἵνα</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> … <span class=\"greek\">μαρτυρήσῃ</span> <span class=\"greek\">αὐτῇ</span> Hs 5, 7, 1.—<span class=\"greek\">ὁ</span> <span class=\"greek\">κύριος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">μαρτυρῶν</span> <span class=\"greek\">ἐπὶ</span> (omitido numa variante textual; <span class=\"greek\">μ</span>. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινι</span> como em Jos., Ant. 3, 189) <span class=\"greek\">τῷ</span> <span class=\"greek\">λόγῳ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">χάριτος</span> <span class=\"greek\">αὐτοῦ</span>, o Senhor que confirmou a palavra de sua graça <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:3</a>. Com <span class=\"greek\">συνευδοκέω</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:48</a>, variante textual.</p><p class=\"entry-text\">ⓑ Voz passiva: receber bom testemunho, ser aprovado (Ep. 12 de Apolônio de Tiana: Philostrat. I 348, 26; Just., D. 29, 1. Exemplos de inscrições em Dssm., NB 93 [BS 265], LO 69, 2 [LAE 84, 5]): <span class=\"greek\">ἀνὴρ</span> <span class=\"greek\">μαρτυρούμενος</span> ou <span class=\"greek\">μεμαρτυρημένος</span>, homem de boa reputação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:3</a>; IPhld 11:1. Dos dignos do AT: pessoas de mérito reconhecido 1 Cl 17:1; 19:1. De Davi 18:1. De Abraão <span class=\"greek\">μεγάλως</span> <span class=\"greek\">ἐμαρτυρήθη</span>, seu mérito recebeu testemunho glorioso 17:2 (cf. Just., D. 11, 5 <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πίστει</span> <span class=\"greek\">μαρτυηθέντος</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>). Dos apóstolos 47:4. De Paulo IEph 12:2. Dos dirigentes eclesiásticos 1 Cl 44:3.—Seguido de nominativo e infinitivo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:4a</a>; cf. v. 5. <span class=\"greek\">διά</span> <span class=\"greek\">τινος</span>, ser louvado por alguma coisa 11:4a, 39. <span class=\"greek\">ἐν</span> <span class=\"greek\">ἔργοις</span> <span class=\"greek\">καλοῖς</span> <span class=\"greek\">μαρτυρούμενος</span>, atestado favoravelmente pelas boas obras <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:10</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:2</a>. <span class=\"greek\">ὑπό</span> <span class=\"greek\">τινος</span>, ser elogiado por alguém (M. Ant. 7, 62; SIG 799, 28; Jos., Ant. 3, 59; Just., D. 29, 3; 92, 4; New Docs 7, 233, n.º 10, 10, acerca de benfeitor) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:22</a>; 16:2; 22:12; IPhld 5:2.—Impessoalmente <span class=\"greek\">μαρτυρεῖταί</span> <span class=\"greek\">τινι</span> <span class=\"greek\">ὑπό</span> <span class=\"greek\">τινος</span>, um bom testemunho é dado por alguém a alguém (Dionys. Hal., Thu. 8 <span class=\"greek\">μαρτυρεῖται</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἀνδρὶ</span> <span class=\"greek\">τάχα</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">ὐπὸ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">φιλοσόφων</span>; BGU 1141, 15 [14 a.C.] <span class=\"greek\">ὡς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μαρτυρηθήσεταί</span> <span class=\"greek\">σοι</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">φίλων</span>): <span class=\"greek\">Δημητρίῳ</span> <span class=\"greek\">μεμαρτύρηται</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">αὐτῆς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀληθείας</span>, Demétrio recebeu bom testemunho de todos e da própria verdade 3J 12a.—Dg 12:6.—OMichel, Bibl. Bekennen u. Bezeugen, <span class=\"greek\">Ὁμολογεῖν</span> und <span class=\"greek\">μαρτυρεῖν</span> im bibl. Sprachgebr.: Evang. Theologie 2, ’35, 231–45; EBurnier, La notion de témoignage dans le NT ’39.—DELG s.v. <span class=\"greek\">μάρτυς</span>. M-M. EDNT. TRE XXII 196–212. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0226-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαρτυρία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μαρτυρία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (ver <span class=\"greek\">μαρτυρέω</span>; Hom. e posteriores—KLatte, Martyria: Pauly-W. XIV 2, 2032–39; Kl. Pauly III 1058).</p><p class=\"entry-text\">① Confirmação ou atestação fundada em conhecimento ou convicção pessoal: testemunho.</p><p class=\"entry-text\">ⓐ Ato de testemunhar, depoimento, prestação de testemunho (Pla., Leg. 11 p. 937a <span class=\"greek\">εἰς</span> <span class=\"greek\">μαρτυρίαν</span> <span class=\"greek\">κληθείς</span>; Epict. 3, 22, 86, a <span class=\"greek\">μ</span>. do cínico; PHal 1, 222 <span class=\"greek\">εἰς</span> <span class=\"greek\">μαρτυρίαν</span> <span class=\"greek\">κλῆσις</span>; Iren. 5, 28, 4 [Harv. II 403, 5] <span class=\"greek\">διὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">κατακριθεὶς</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">θηρία</span>): <span class=\"greek\">οὗτος</span> <span class=\"greek\">ἦλθεν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">μαρτυρίαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:7</a>. Sobre as duas testemunhas: <span class=\"greek\">ὅταν</span> <span class=\"greek\">τελέσωσιν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">μαρτυρίαν</span> <span class=\"greek\">αὐτῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:7</a>.</p><p class=\"entry-text\">ⓑ Conteúdo do testemunho.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Testemunho ou atestação histórica (Diod S 11, 38, 6 <span class=\"greek\">τῆς</span> <span class=\"greek\">ἱστορίας</span> <span class=\"greek\">δικαία</span> <span class=\"greek\">μαρτυρία</span>; Just., D. 79, 2 <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἠσαίου</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.35\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:35</a>; 21:24 (JChapman, JTS 31, 1930, 379–87); Papias (2:17).</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Especialmente referente a Jesus.</p><p class=\"entry-text\"><span class=\"hebrew\" dir=\"rtl\">א</span> . Do testemunho humano acerca de Jesus: de João Batista <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:19</a>; de Paulo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:18</a> (ver TRE XXIII 23–31); dos crentes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:11</a>. O testemunho humano é rejeitado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.34\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:34</a>.</p><p class=\"entry-text\"><span class=\"hebrew\" dir=\"rtl\">ב</span> . Do testemunho transcendente acerca de Jesus: ele testemunha a respeito de si mesmo como centro da mensagem cristã: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:11</a>, 32s.; 8:14. Sua autoatestação é rejeitada v. 13; cf. 5:31. Jesus também testemunha acerca de si mesmo em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:2</a>, 9.—Deus o atesta (cf. Ael. Aristid. 45 p. 12 D.: <span class=\"greek\">μ</span>. <span class=\"greek\">παρὰ</span> <span class=\"greek\">Ἀπόλλωνος</span>, p. 13 <span class=\"greek\">ἐκ</span> <span class=\"greek\">Διός</span>; Dexippus Athen. [século III d.C.]:100 Fgm. 1, 7 Jac. <span class=\"greek\">ἡ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">μ</span>. referente ao “deus” Licurgo) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.32\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:32</a>, 36 (<span class=\"greek\">μαρτυρία</span> <span class=\"greek\">μείζων</span> como em Dionys. Soph., Ep. 77.—Cf. Orig., C. Cels. 8, 9, 25 <span class=\"greek\">τὰ</span> <span class=\"greek\">ὑπ</span>’ <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">γενόμενα</span> <span class=\"greek\">παράδοξα</span> … <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">εἶχε</span> <span class=\"greek\">μ</span>.). 1J 5:9bc, 10ab, 11.—RAsting (ver <span class=\"greek\">εὐαγγέλιον</span>, final).—Acerca de João, ver EHoskyns, The Fourth Gosp., ed. FDavey ’47 p. 58–95.</p><p class=\"entry-text\"><span class=\"hebrew\" dir=\"rtl\">ג</span> . Apocalipse fala da <span class=\"greek\">μαρτυρία</span> ou <span class=\"greek\">μ</span>. <span class=\"greek\">Ἰησοῦ</span> possuída pelos cristãos ou por determinados cristãos (mártires, profetas): 6:9; 12:17; 19:10ab; 20:4.—FMazzaferri, Bible Translator 39, ’88, 114–22: o livro de João é o testemunho pessoal de Jesus.</p><p class=\"entry-text\">② Depoimento em juízo, testemunho (Demosth. 29, 7 e outros; Jos., Ant. 4, 219) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.56\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:56</a>, 59; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.71\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:71</a>. <span class=\"greek\">κατά</span> <span class=\"greek\">τινος</span>, contra alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.55\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:55</a>; <span class=\"greek\">δύο</span> <span class=\"greek\">ἀνθρώπων</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">μ</span>., o testemunho de duas pessoas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.17\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:17</a>.</p><p class=\"entry-text\">③ Atestação de caráter ou conduta: testemunho, declaração de aprovação (Jos., Ant. 6, 346; cf. Did., Gen. 212, 1) 1J 5:9a; 3J 12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:13</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀγαθῆς</span> <span class=\"greek\">πράξεως</span>, testemunho acerca de boas obras 1 Cl 30:7. <span class=\"greek\">μαρτυρίαν</span> <span class=\"greek\">καλὴν</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἔξωθεν</span>, ter boa reputação entre os de fora <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:7</a> (<span class=\"greek\">μ</span>.=recomendação: Dio Chrys. 28 [45], 9; Chion, Ep. 2; SIG1073, 17 [século II d.C.]).—Na obscura sequência de orações de 1:6, o amor parece ser <span class=\"greek\">ἔργων</span> <span class=\"greek\">δικαιοσύνης</span> <span class=\"greek\">μαρτυρία</span>, testemunho de obras justas.—De um bom testemunho dado por Deus (Dio Chrys. 16 [33], 12 <span class=\"greek\">τῆς</span> <span class=\"greek\">μεγίστης</span> <span class=\"greek\">ἔτυχε</span> <span class=\"greek\">μαρτυρίας</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">δαιμονίου</span>) Hs 5, 2, 6.</p><p class=\"entry-text\">④ Testemunho que conduz à morte, morte de mártir, martírio (Iren. 1, 28, 1 [Harv. I 220, 10]) MPol 1:1; 13:2; 17:1.—DELG s.v. <span class=\"greek\">μάρτυς</span>. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0226-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαρτύριον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μαρτύριον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (ver <span class=\"greek\">μάρτυς</span>; Pind., Hdt. e posteriores; inscrições, papiros, LXX frequentemente; EpArist 306; Philo, Joseph., Just.).</p><p class=\"entry-text\">① Aquilo que serve de testemunho ou prova: testemunho, evidência.</p><p class=\"entry-text\">ⓐ Consistente em ato, circunstância ou objeto que serve de testemunho (Pla., Leg. 12, 943c [<span class=\"greek\">τ</span>. <span class=\"greek\">στέφανον</span>] <span class=\"greek\">ἀναθεῖναι</span> <span class=\"greek\">μαρτύριον</span> <span class=\"greek\">εἰς</span> … <span class=\"greek\">κρίσιν</span>; Jos., Ant. 6, 66; Just., D. 141, 3; Did., Gen. 63, 24): <span class=\"greek\">προσένεγκον</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">δῶρον</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">μαρτύριον</span> <span class=\"greek\">αὐτοῖς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:4</a> (JZoller, ‘Z. Zeugnis für sie’: Ricerche Relig. 5, 1929, 385–91 contra SZeitlin: Rev. des Études juives 87, 1929, 79–82); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:14</a>. <span class=\"greek\">ἐκτινάξατε</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">χοῦν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">μ</span>. <span class=\"greek\">αὐτοῖς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:11</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:5</a> (<span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτούς</span>). <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ἡγεμόνας</span> <span class=\"greek\">ἀχθήσεσθε</span> <span class=\"greek\">ἕνεκεν</span> <span class=\"greek\">ἐμοῦ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">μαρτύριον</span> <span class=\"greek\">αὐτοῖς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:18</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:9</a>; <span class=\"greek\">ἀποβήσεται</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">μ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:13</a> (ver <span class=\"greek\">ἀποβαίνω</span> 2). <span class=\"greek\">κηρυχθήσεται</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὅλῃ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">οἰκουμένῃ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">μ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:14</a>. <span class=\"greek\">ἐδίδου</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>., (Paulo) dava testemunho (enfrentando destemidamente o leão) AcPl Ha 4, 28 (cf. Kaibel 397, 1 <span class=\"greek\">μαρτύριον</span> <span class=\"greek\">ὀρθοῦ</span> <span class=\"greek\">βίου</span>, “testemunho de uma vida íntegra”).—Uma declaração oral serve <span class=\"greek\">εἰς</span> <span class=\"greek\">μ</span>., como testemunho 9:3; IPhld 6:3; uma declaração escrita <span class=\"greek\">εἰς</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ὑμῖν</span> (cf. Dt 31:26) ITr 12:3. O fato de certos números aparecerem no AT serve de indício, equivalente a um testemunho, de determinados detalhes do plano da salvação 8:3s.; cf. GEb 34, 62. A morte redentora de Jesus constituiu um testemunho (de Deus) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:6</a> (outros encontram o referente no v. 5). A ferrugem do dinheiro dos ricos se converterá <span class=\"greek\">εἰς</span> <span class=\"greek\">μ</span>., em testemunho contra eles <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:3</a>. Moisés, como servo (cujo serviço se destina) <span class=\"greek\">εἰς</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">λαληθησομένων</span>, a dar testemunho das revelações futuras <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:5</a>. A <span class=\"greek\">μείωσις</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκός</span> como <span class=\"greek\">μ</span>. <span class=\"greek\">ἐκλογῆς</span>, testemunho ou prova de eleição Dg 4:4.</p><p class=\"entry-text\">ⓑ Consistente numa declaração apresentada como testemunho: com genitivo subjetivo <span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">συνειδήσεως</span>, o testemunho prestado por nossa consciência <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:12</a>. Com genitivo objetivo <span class=\"greek\">ἀπεδίδουν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>. … <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀναστάσεως</span>, davam testemunho da ressurreição <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:33</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">σταυροῦ</span>, o testemunho da cruz Pol 7:1. Da pregação cristã e do evangelho em geral: <span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span>, testemunho de Cristo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:6</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:8</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, testemunho de Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:1</a>. <span class=\"greek\">ἐπιστεύθη</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ὑμᾶς</span>, nosso testemunho dirigido a vós foi aceito <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 1:10</a>.</p><p class=\"entry-text\">② Empregado na LXX como tradução de <span class=\"hebrew\" dir=\"rtl\">מוֹעֵד</span> na expressão <span class=\"greek\">ἡ</span> <span class=\"greek\">σκηνὴ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μ</span>.=<span class=\"hebrew\" dir=\"rtl\">אֹהֶל</span> <span class=\"hebrew\" dir=\"rtl\">מוֹעֵד</span>, tenda do encontro, tabernáculo do testemunho (Ex 28:43 e outros; Just.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.44\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.15.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 15:5</a>; 1 Cl 43:2, 5.</p><p class=\"entry-text\">③ Martírio Papias (12:1); MPol 1:1; 2:1; 18:3; 19:1; EpilMosq 2; Phlm subscr., variante textual.—Quanto à ausência em João, ver M-EBoismard, Le Chapitre 21 de St Jean: RB ’54 (’47), 482.—DELG s.v. <span class=\"greek\">μάρτυς</span>. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0226-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαρτύρομαι</h1><div class=\"entry-meta\"><span>verbo médio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μαρτύρομαι</span>, infinitivo aoristo <span class=\"greek\">μαρτύρασθαι</span> 1 Macc 2:56 (trágicos, Thu. e outros; papiros, LXX, Did.).</p><p class=\"entry-text\">① Afirmar alguma coisa solenemente: testificar, dar testemunho (Pla., Phileb. 47d; Jos., Bell. 3, 354; POxy 1120, 11; PAmh II, 141, 17; PStras I, 5, 14; 1 Macc 2:56 <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐκκλησίᾳ</span>). <span class=\"greek\">τινί</span>, a alguém: <span class=\"greek\">μικρῷ</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μεγάλῳ</span>, a pequenos e grandes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:22</a>. <span class=\"greek\">τινί</span>, com <span class=\"greek\">ὅτι</span> seguinte 20:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:3</a>.</p><p class=\"entry-text\">② Exortar a alguma coisa como questão de grande importância: afirmar, insistir, implorar (a alguém: Polyb. 13, 8, 6; Jdth 7:28; Jos., Ant. 10, 104), com <span class=\"greek\">λέγειν</span> e acusativo seguido de infinitivo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:17</a>. <span class=\"greek\">τινά</span> seguido de <span class=\"greek\">εἰς</span> e infinitivo substantivado com acusativo: <span class=\"greek\">παρακαλοῦντες</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">παραμυθούμενοι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μαρτυρόμενοι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">περιπατεῖν</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">ἀξίως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:12</a>.—DELG s.v. <span class=\"greek\">μάρτυς</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0226-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μάρτυς, μάρτυρος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μάρτυς</span>, <span class=\"greek\">μάρτυρος</span>, <span class=\"greek\">ὁ</span>, dativo plural <span class=\"greek\">μάρτυσιν</span> (Pind., Hdt. e posteriores; inscrições, papiros, LXX; TestAbr A 13 p. 92, 22 [Stone p. 32]; TestLevi 19:3; Philo, Joseph.; apolog. exc. Ar.).</p><p class=\"entry-text\">① Aquele que depõe em questões jurídicas: testemunha (Just., A I, 23, 3; Ath. 3, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.58\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:58</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 13:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:19</a> (os três últimos segundo Dt 19:15; cf. Jos., Vi. 256 e Hipponax [século VI a.C.] 47 D.3 <span class=\"greek\">ἐλθὼν</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">τριοῖσι</span> <span class=\"greek\">μάρτυσιν</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.28\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:28</a> (Dt 17:6.—<span class=\"greek\">ἐπὶ</span> <span class=\"greek\">μάρτυσι</span> também em Appian, Bell. Civ. 3, 14 §49). <span class=\"greek\">τί</span> <span class=\"greek\">ἔτι</span> <span class=\"greek\">χρείαν</span> <span class=\"greek\">ἔχομεν</span> <span class=\"greek\">μαρτύρων</span>;, que necessidade temos ainda de testemunhas? (Pla., Rep. 1, 340a <span class=\"greek\">τί</span> <span class=\"greek\">δεῖται</span> <span class=\"greek\">μάρτυρος</span>; <span class=\"greek\">αὐτὸς</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Θρασύμαχος</span> <span class=\"greek\">ὁμολογεῖ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.65\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:65</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.63\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:63</a>. <span class=\"greek\">μάρτυρες</span> <span class=\"greek\">ψευδεῖς</span>, falsas testemunhas (Demosth. 29, 28) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:13</a> (Mel., P. 79, 572). Há sugestão de protocolo administrativo no relato dos homens prudentes e irrepreensíveis que a igreja romana enviou a Corinto e que <span class=\"greek\">μάρτυρες</span> <span class=\"greek\">ἔσονται</span> <span class=\"greek\">μεταξὺ</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἡμῶν</span> 1 Cl 63:3.</p><p class=\"entry-text\">② Aquele que afirma ou atesta: atestador, testemunha, sentido transferido da acepção 1, referente a qualquer pessoa que pode ou deve testemunhar acerca de alguma coisa.</p><p class=\"entry-text\">ⓐ De Deus (ou do Cristo exaltado) como testemunha (divindades como testemunhas frequentemente em Pind. e outros; Philo; Jos., Bell. 1, 595, Ant. 1, 209; TestLevi 19:3; SibOr, Fgm. 1, 4; Just., A II, 12, 4 <span class=\"greek\">θεὸν</span> … <span class=\"greek\">μάρτυρα</span> <span class=\"greek\">ἔχοντες</span>; Orig., C. Cels. 1, 46, 26 <span class=\"greek\">θεὸς</span> [subentende-se <span class=\"greek\">ἐστιν</span>] <span class=\"greek\">μ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἡμετέρου</span> <span class=\"greek\">συνειδότος</span>); fórmula “Deus é minha testemunha” (de que falo a verdade) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:8</a>; abreviada <span class=\"greek\">θεὸς</span> <span class=\"greek\">μ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:5</a>; cf. v. 10 (aqui também Jos., Ant. 15, 130 <span class=\"greek\">μ</span>. <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">ποιούμενος</span>). <span class=\"greek\">μ</span>. <span class=\"greek\">μοι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">δέδεμαι</span> IPhld 7:2. <span class=\"greek\">μάρτυρα</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">ἐπικαλεῖσθαι</span>, invocar Deus como testemunha <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:23</a> (cf. 1 Km 12:5s.; 20:23; Polyb. 11, 6, 4 <span class=\"greek\">τ</span>. <span class=\"greek\">θεοὺς</span> <span class=\"greek\">ἐπικαλέσεσθε</span> <span class=\"greek\">μάρτυρας</span>; Heliod. 1, 25, 1; Galen VI 775 Kühn; igualmente da invocação de divindades, Hippol., Ref. 9, 15, 6: <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἑπτὰ</span> <span class=\"greek\">μάρτυρας</span> <span class=\"greek\">μαρτύρομαι</span>).</p><p class=\"entry-text\">ⓑ De seres humanos (cf. Pind. O. 4, 5), testemunhas oculares e auriculares (X., Ages. 4, 5; Pla., Ep. 1 p. 309a; Aelian, VH 10, 6; Jos., Ant. 18, 299; Tat. 31, 1; 36, 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:2</a>.—Também de testemunhas cuja fé foi provada e se mostrou verdadeira: <span class=\"greek\">τοσοῦτον</span> <span class=\"greek\">νέφος</span> <span class=\"greek\">μαρτύρων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:1</a>.—De testemunhas de acontecimentos que conhecem sem os terem experimentado pessoalmente (segundo Strabo 7, 3, 7 p. 300, Hesíodo é <span class=\"greek\">μάρτυς</span> a respeito dos citas): os doutores da lei testemunham o assassinato dos profetas por seus antepassados ao erigirem túmulos para os profetas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:48</a> (<span class=\"greek\">μαρτυρεῖτε</span>, variante textual).</p><p class=\"entry-text\">ⓒ De testemunhas portadoras de mensagem divina (Epict. 3, 26, 28, Deus usa os sábios como seus <span class=\"greek\">μάρτυρες</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:3</a> (embora o sentido aqui se aproxime de “mártir” [ver 3 abaixo]; cf. v. 7. Ver DHaugg, D. zwei Zeugen-Apk 11:1–13, ’36; JConsidine, CBQ 8, ’46, 377–92). Nesse sentido, sobretudo os discípulos de Jesus como testemunhas de sua vida, morte e ressurreição: <span class=\"greek\">ἔσεσθέ</span> <span class=\"greek\">μου</span> <span class=\"greek\">μάρτυρες</span>, sereis minhas testemunhas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:8</a>; cf. 13:31 (Ps.-Demetr. 222 <span class=\"greek\">μάρτυς</span> <span class=\"greek\">σου</span> <span class=\"greek\">γίνεται</span>). Com genitivo objetivo da coisa testemunhada: testemunha a respeito de (Jos., C. Ap. 1, 4 <span class=\"greek\">τῶν</span> <span class=\"greek\">ὑπ</span>’ <span class=\"greek\">ἐμοῦ</span> <span class=\"greek\">λεγομένων</span> <span class=\"greek\">μ</span>., Ant. 4, 40; <span class=\"greek\">ἀληθείας</span> <span class=\"greek\">μ</span>. de Policarpo Iren. 3, 3, 4 [Harv. II 13, 4]; <span class=\"greek\">παραδόσεως</span> da comunidade de Éfeso 3, 3, 4 [Harv. II 15, 6]; Orig., C. Cels. 1, 47, 24) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:48</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:22</a>; 3:15; 5:32; 10:39; 26:16. <span class=\"greek\">μ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span> <span class=\"greek\">παθημάτων</span>, testemunha dos sofrimentos de Cristo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:1</a>. <span class=\"greek\">ἔσῃ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">πάντας</span> <span class=\"greek\">ἀνθρώπους</span>, serás testemunha dele diante de todos os homens <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:15</a> (Epict. 3, 24, 113 <span class=\"greek\">μ</span>. <span class=\"greek\">πρὸς</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἄλλους</span>).—10:41. Danker, Benefactor 442–47.</p><p class=\"entry-text\">③ Aquele que testemunha ao preço da própria vida: mártir, no uso da igreja perseguida. <span class=\"greek\">τὸ</span> <span class=\"greek\">αἷμα</span> <span class=\"greek\">Στεφάνου</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μάρτυρός</span> <span class=\"greek\">σου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:20</a>. De Antipas: <span class=\"greek\">ὁ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">μου</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">πιστός</span> <span class=\"greek\">μου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:13</a> (cf. Pind., P. 1, 88 <span class=\"greek\">μάρτυρες</span> <span class=\"greek\">πιστοί</span>=“testemunhas confiáveis”; sobre os problemas textuais de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:13</a>, ver RBorger, TRu 52, ’87, 45–47). Onésimo <span class=\"greek\">μ</span>. <span class=\"greek\">Χριστοῦ</span> <span class=\"greek\">γεγένηται</span> Phlm subscr., variante textual. Em geral <span class=\"greek\">μάρτυρες</span> <span class=\"greek\">Ἰησοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 17:6</a>; cf. MPol 2:2; 14:2; 15:2; 16:2, variante textual; 17:3; 19:1. De Zacarias: <span class=\"greek\">μ</span>. <span class=\"greek\">εἰμι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> GJs 25:3 (ver de Strycker, comentário ao lugar). Como Apocalipse também chama Jesus (assim como Antipas) <span class=\"greek\">ὁ</span> <span class=\"greek\">μάρτυς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">πιστός</span> 1:5; 3:14, essas passagens provavelmente devem ser incluídas aqui (cf. Ps 88:38), mas reconhecendo que em todas as passagens neotestamentárias desta classificação há forte ênfase no fato de testemunhar. A morte de Jesus foi cedo considerada o primeiro martírio.—Sobre a questão de como <span class=\"greek\">μάρτυς</span>=“testemunha” veio a significar “mártir”, ver FKattenbusch, ZNW 4, 1903, 111ss.; KHoll, em diversos trabalhos, depois Gesamm. Aufsätze II 1928, 103ss.; ASchlatter, BFChTh 19, 3, 1915; PCorssen, NJklA 35, 1915, 481ss., 37, 1916, 424ss., ZNW 15, 1914, 221ss., com várias continuações até 18, 1917, 249ss., Sokrates 6, 1918, 106ss.; Rtzst., Hist. Mon. 1916, 85; 257, NGG 1916, 417ss., Her 52, 1917, 442ss.; FDornseiff, ARW 22, 1923/24, 133ss.; HDelehaye, Analecta Bollandiana 39, 1921, 20ss., Sanctus 1927 (2’33), 74ss. (75, 1 bibliografia). ELohmeyer, D. Idee des Martyriums im Judent. u. Urchristent.: ZST 5, 1927/28, 232–49; GFitzer, D. Begriff des <span class=\"greek\">μ</span>. im Judent. u. Urchristent., diss. Bresl. 1929; HLietzmann, Martys: Pauly-W. XIV 2, 1930, 2044–52; OMichel, Prophet u. Märt. ’32; RCasey, <span class=\"greek\">Μάρτυς</span>: Beginn. I 5, ’33, 30–37; EStauffer, Märtyrertheologie u. Täuferbewegg.: ZKG 52, ’33, 545–98; DRiddle, The Martyr Motif in Mk: JR 4, 1924, 174–91, Hb, 1 Cl and the Persecution of Domitian: JBL 43, 1924, 329–48, From Apocalypse to Martyrology: ATR 9, 1927, 260–80, The Martyrs: A Study in Social Control ’31, Die Verfolgungslogien im formgesch. u. soziol. Bed.: ZNW 33, ’34, 271–89; HvCampenhausen, D. Idee des Martyriums in d. alten Kirche2 ’64; EPeterson, Zeuge d. Wahrh. ’37; EBurnier, Le notion de témoignage dans le NT ’37; HSurkau, Martyrien in jüd. u. frühchristl. Zt. ’38; HFischel, Martyr and Prophet (in Jewish lit.), JQR 37, ’46/47, 265–80; 363–86; EGünther, <span class=\"greek\">Μάρτυς</span>, D. Gesch. eines Wortes ’41, Zeuge u. Märtyrer, ZNW 47, ’56, 145–61. ELohse, Märtyrer u. Gottesknecht ’55; HvanVliet, No Single Testimony (Dt 19:15) ’58; NBrox, Zeuge u. Märtyrer ’61.—B. 1436; ATrites, <span class=\"greek\">Μάρτυς</span> and Martyrdom in the Apocalypse, A Semantic Study: NovT 15, ’73, 72–80, The NT Concept of Witness ’77; GDragas, Martyrdom and Orthodoxy in the NT Era: Greek Orthodox Theological Review 30, ’85, 287–96; PVassiliadis, The Translation of <span class=\"greek\">μαρτυρία</span> <span class=\"greek\">Ιησοῦ</span> in Rv: BT 36, ’85, 129–34; M-ERosenblatt, Paul the Accused ’95, 1–21; Kl. Pauly III 1059s.; BHHW II 1156s.—DELG. M-M. EDNT. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0226-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαρυκάομαι</h1><div class=\"entry-meta\"><span>verbo médio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μαρυκάομαι</span> (forma dórica popularizada [Aelian, NA 2, 54; Hesych. s.v. <span class=\"greek\">ἐμαρυκᾶτο</span> e <span class=\"greek\">ἤνυστρον</span>; Lev 11:26=Dt 14:8; ver Thackeray 76]), ruminar, remoer, Hs 9, 1, 9. <span class=\"greek\">πᾶν</span> <span class=\"greek\">μαρυκώμενον</span>, todo ruminante 10:11.—PKatz, Philo’s Bible ’50, 157–59.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0226-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μασάομαι</h1><div class=\"entry-meta\"><span>verbo médio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μασάομαι</span> (<span class=\"greek\">μασς</span>-, forma menos correta, variante textual), imperfeito <span class=\"greek\">ἐμασώμην</span> (Aristoph., Hippocr. e outros; Artem. 4, 33; Philostrat., Vi. Apoll. 7, 21 p. 276, 2; PGM 5, 280; Job 30:4; Jos., Bell. 6, 197; Just., D. 57, 2), morder, com acusativo: <span class=\"greek\">τὰς</span> <span class=\"greek\">γλώσσας</span>, morder a própria língua <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 16:10</a>; ApcPt 14:29. <span class=\"greek\">τὰ</span> <span class=\"greek\">χείλη</span>, morder os lábios 13:28. Na visão de José, <span class=\"greek\">οἱ</span> <span class=\"greek\">μασώμενοι</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐμασῶντο</span> GJs 18:2 (códices, não Bodmer).—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0226-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μασθός</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μασθός</span>: ver <span class=\"greek\">μαστός</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0226-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαστιγόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μαστιγόω</span>, futuro <span class=\"greek\">μαστιγώσω</span>; 1º aoristo <span class=\"greek\">ἐμαστίγωσα</span>. Passivo: futuro 3ª pessoa do plural <span class=\"greek\">μαστιγωθήσονται</span> Ps 72:5; 1º aoristo <span class=\"greek\">ἐμαστιγώθην</span>; perfeito <span class=\"greek\">μεμαστίγωμαι</span> LXX (“açoitar, flagelar”, Hdt. e outros; inscrições, papiros, LXX; Philo, In Flacc. 85; Joseph.; TestJos 8:4, variante textual).</p><p class=\"entry-text\">① Bater com chicote ou açoite: açoitar, flagelar, fustigar.</p><p class=\"entry-text\">ⓐ Do açoite como punição decretada pela sinagoga (Dt 25:2s.; ver tratado mishnaico Sanhedrin-Makkoth, editado com notas por SKrauss ’33), com acusativo da pessoa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:17</a>; 23:34. Do açoite aplicado a Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.1\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:1</a>. Se João se refere à “verberatio” imposta aos condenados à morte (TMommsen, Röm. Strafrecht 1899, 938s.; Jos., Bell. 2, 308; 5, 449), é estranho que Pilatos declare depois não encontrar motivo para agir (v. 6); mas, se essa última afirmação se refere somente à pena da crucificação, <span class=\"greek\">μ</span>. v. 1 pode equivaler a <span class=\"greek\">παιδεύω</span> (ver 2b<span class=\"greek\">γ</span>) em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:16</a>, 22 (para <span class=\"greek\">μ</span>. de infração não punível com morte, PFlor I, 61, 61 [85 d.C.]=Mitt-Wilck. II/2, 80 II, 61). A “verberatio” é designada nas predições da Paixão e explicitamente como ação de não israelitas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:33</a>.—Como punição por fraude em competições atléticas (Ps.-Dionys. Hal., Ars Rhet. 7, 6 p. 292, 5 R. <span class=\"greek\">μάστιγες</span> … <span class=\"greek\">κ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐκβάλλεσθαι</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">σταδίων</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἀγώνων</span>) 2 Cl 7:4. Do açoite como punição no mundo inferior ApcPt Bodl, no v. 34 (para <span class=\"greek\">τύπτοντες</span>, texto Akhmim, linha 107 Dieterich).</p><p class=\"entry-text\">ⓑ Em geral, em sentido transferido: afligir, atormentar, maltratar (Artem. 1, 24 p. 25, 16 <span class=\"greek\">μ</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">ὧτα</span>=“puxar as orelhas”; UPZ 119, 29; 44 [156 a.C.]; Sir 30:14) ITr 4:1; Hs 6, 3, 1.</p><p class=\"entry-text\">② Punir visando à disciplina: punir, corrigir, extensão metafórica da acepção 1; de Deus (Jer 5:3; Jdth 8:27) com finalidade disciplinar (Maximus Tyr. 19, 5e, da alma) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:6</a>; 1 Cl 56:4, ambos Pr 3:12.—DELG s.v. <span class=\"greek\">μάστιξ</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0226-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαστίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μαστίζω</span>, aoristo <span class=\"greek\">ἐμάστιξα</span> LXX; TestJos 8:4 (Hom. e posteriores; Diod S 14, 112, 2; Plut., Mor. 165e; Lucian, Pro Imag. 24; inscrição palestina: SEG VIII, 246, 17 [século II d.C.]; LXX, TestSol, Test12Patr, ApcEsdr 4:22 p. 28, 26 Tdf.), golpear com chicote GPt 3:9. Especificamente do interrogatório mediante tortura: flagelar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:25</a> (era proibido submeter um cidadão romano ao açoitamento: Cicero, Verr. 2, 5, 66; Appian, Bell. Civ. 2, 26 §98. Além disso, ver HCadbury, Beginn. V ’33, 297–338, especialmente 319; Haenchen, comentário ao lugar).—DELG s.v. <span class=\"greek\">μάστιξ</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0226-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μάστιξ, ιγος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μάστιξ</span>, <span class=\"greek\">ιγος</span>, <span class=\"greek\">ἡ</span> (“chicote, açoite”, usado especialmente para impelir cavalos ou trabalhadores: Hom. e posteriores; inscrições, papiros, LXX, En; ApcrEzk [Epiph 70, 15]; Just., A I, 5, 1; Mel.).</p><p class=\"entry-text\">① Instrumento flexível usado para açoitar: chicote, açoite Hs 6, 2, 5. Principalmente no plural: açoites, golpes de chicote (Jos., Bell. 2, 306, Vi. 147; Mel., P. 79, 573 e outros) 5:14 (Is 50:6); MPol 2:2; Hv 3, 2, 1. <span class=\"greek\">μάστιξιν</span> <span class=\"greek\">ἀνετάζειν</span> <span class=\"greek\">τινά</span>, interrogar alguém mediante açoitamento <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:24</a> (cf. PAmh 31 I, 10s.; ver Taubenschlag, OpMin II 723, sobre o processo de interrogatório). Com <span class=\"greek\">ἐμπαιγμός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.36\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:36</a>.</p><p class=\"entry-text\">② Condição de grande aflição: tormento, sofrimento, extensão figurada da acepção 1 (enviado por Deus aos humanos: Il. 12, 37 <span class=\"greek\">Διὸς</span> <span class=\"greek\">μ</span>.; Proverbia Aesopi 105 P.; Ps 38:11; 2 Macc 7:37; 9:11; En 25:6; 100, 13; inscrição em CB I/2, 520 n.º 361 <span class=\"greek\">λήψεται</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">μάστειγα</span> <span class=\"greek\">αἰώνιον</span>; também referido a divindades nocivas, Just., A I, 5, 1): de doença corporal <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:10</a>; 5:29, 34; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:21</a>. Das aflições de um pecador 1 Cl 22:8 (Ps 31:10); Hv 4, 2, 6. Com <span class=\"greek\">αἰκίσματα</span>, das pragas do Egito 1 Cl 17:5 (Mel., P. 11, 75s.). <span class=\"greek\">μ</span>. <span class=\"greek\">γλώσσης</span>, açoite da língua 1 Cl 56:10 (Job 5:21).—Eitrem (ver <span class=\"greek\">πειράζω</span> 4, final) 12s.—DELG. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0226-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαστός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μαστός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (formas colaterais <span class=\"greek\">μασθός</span> GJs Bodmer [Heraclid. Miles., Fgm. 25 LCohn 1884; IG III, 238b; POslo 95, 19: 96 d.C.; PGM 7, 208; TestSol 9:4 H; JosAs 8:4 cód. A; 29:11 cód. A; Thackeray 104] e <span class=\"greek\">μαζός</span> [ver o verbete] são encontradas como variantes textuais, mas mais frequentemente <span class=\"greek\">μασθός</span>; ver Kühner-Bl. I 157; B-D-F §34, 5; W-S. §5, 27d; Mlt-H. 110), “um dos seios” (no plural, em linguagem figurada, Jos., Bell. 7, 189; Mel.), distinto de <span class=\"greek\">στῆθος</span>, “peito”; ver citação de Hom. no verbete <span class=\"greek\">μαζός</span>.</p><p class=\"entry-text\">① Uma das papilas mamárias de um homem: mamilo (X., An. 4, 3, 6, da água <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">μαστῶν</span>; Eratosth. p. 33, 2; SIG 1170, 24; TestSol 9:4 LC, em oposição a <span class=\"greek\">στῆθος</span>: um espírito hostil [<span class=\"greek\">δαίμων</span>] a quem Salomão pôs um selo no peito é interrogado sobre como enxerga. Resposta: “pelos meus seios” = seus mamilos, que funcionam como olhos): <span class=\"greek\">περιεζωσμένος</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ζώνην</span> <span class=\"greek\">χρυσᾶν</span>, com um cinto de ouro ao redor do peito <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:13</a> (<span class=\"greek\">μασθοῖς</span> Tdf. no texto; Diod S 1, 72, 2 <span class=\"greek\">περιεζωσμένοι</span> <span class=\"greek\">ὑποκάτω</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">μαστῶν</span>).</p><p class=\"entry-text\">② Glândula mamária de uma mulher: seio (Hdt. e outros; Sb 6706, 9; LXX; ApcEsdr 5:2 p. 29, 26 Tdf.; Philo, Op. M. 38; Mel., P. 52, 384) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:27</a>; 23:29; GJs 5:2; 6:3; 19:2; ApcPt Fgm. 2 p. 12, 25.—DELG. M-M.</p></section></article>"};
